def most_frequent_brand(recommendations):
    brand_counts = {}
    for brand in recommendations:
        brand_counts[brand] = brand_counts.get(brand, 0) + 1

    max_count = max(brand_counts.values())
    most_frequent_brands = [brand for brand, count in brand_counts.items() if count == max_count]

    if len(most_frequent_brands) == 1:
        return most_frequent_brands[0]
    else:
        return sorted(most_frequent_brands)

