    if not all(1 <= rating <= 10 for rating in ratings):
        return "invalid input"

    # Calculate the average rating
    avg_rating = sum(ratings) / len(ratings)

    # Determine if the average rating matches the given narrative
    if narrative == "positive" and avg_rating > 7:
        return "narrative matches"
    elif narrative == "neutral" and 4 <= avg_rating <= 7:
        return "narrative matches"
    elif narrative == "negative" and avg_rating < 4:
        return "narrative matches"
    else:
        return "narrative mismatch"

