def categorize_reviews(reviews):
    positive_reviews = []
    negative_reviews = []
    neutral_reviews = []

    # List of positive and negative keywords
    positive_keywords = ["loved", "amazing", "great", "fantastic", "wonderful", "excellent"]
    negative_keywords = ["disappointing", "terrible", "awful", "bad", "horrible", "poor"]

    for review in reviews:
        review = review.lower()  # Convert to lowercase for easier matching
        positive_match = any(keyword in review for keyword in positive_keywords)
        negative_match = any(keyword in review for keyword in negative_keywords)

        if positive_match and not negative_match:
            positive_reviews.append(review)
        elif negative_match and not positive_match:
            negative_reviews.append(review)
        else:
            neutral_reviews.append(review)

    return {
        "positive": positive_reviews,
        "negative": negative_reviews,
        "neutral": neutral_reviews
    }

def parse_csv(file_path):
    import csv

    violations = []

    with open(file_path, 'r') as file:
        reader = csv.DictReader(file)
        headers = reader.fieldnames

        for row in reader:
            violation = {}
            for header in headers:
                value = row.get(header, None)
                violation[header] = value
            violations.append(violation)

    return violations

