def determine_match_outcome(events):
    home_score = 0
    away_score = 0

    for event in events:
        if event["action"] == "goal":
            if event["team"] == "home":
                home_score += 1
            else:
                away_score += 1
        elif event["action"] == "own goal":
            if event["team"] == "home":
                away_score += 1
            else:
                home_score += 1

    if home_score > away_score:
        return "Home win"
    elif away_score > home_score:
        return "Away win"
    else:
        return "Draw"

