def count_unique_policy_areas(proposals):
    policy_areas = set()
    for proposal in proposals:
        start = proposal.find('[')
        while start != -1:
            end = proposal.find(']', start)
            if end != -1:
                policy_area = proposal[start+1:end]
                policy_areas.add(policy_area)
            start = proposal.find('[', end)
    return len(policy_areas)
