        focus = session['focus']

        if time_of_day not in time_of_day_stats:
            time_of_day_stats[time_of_day] = {'mood_sum': 0, 'focus_sum': 0, 'count': 0}

        time_of_day_stats[time_of_day]['mood_sum'] += mood
        time_of_day_stats[time_of_day]['focus_sum'] += focus
        time_of_day_stats[time_of_day]['count'] += 1

    for time_of_day, stats in time_of_day_stats.items():
        count = stats['count']
        average_mood = round(stats['mood_sum'] / count, 1)
        average_focus = round(stats['focus_sum'] / count, 1)
        time_of_day_stats[time_of_day] = {'average_mood': average_mood, 'average_focus': average_focus}

    return time_of_day_stats

