    def get_relationship(char1, char2):
        if (char1, char2) in relationships:
            return relationships[(char1, char2)]
        elif (char2, char1) in relationships:
            return relationships[(char2, char1)]
        else:
            return "unknown"

    twist_characters = random.sample(characters, random.randint(2, len(characters)))
    twist_relationships = [get_relationship(twist_characters[i], twist_characters[j])
                           for i in range(len(twist_characters))
                           for j in range(i + 1, len(twist_characters))]

    twist_text = f"Plot Twist: {', '.join(twist_characters)} are actually "

    if "enemy" in twist_relationships:
        twist_text += "sworn enemies who have been secretly working together!"
    elif "friend" in twist_relationships:
        twist_text += "not really friends, but have been deceiving each other all along!"
    elif "sibling" in twist_relationships:
        twist_text += "not actually siblings, but have been pretending to be related!"
    else:
