        }

    total_belief_score = 0
    total_skepticism_score = 0

    for statement in statements:
        total_belief_score += statement['belief_score']
        total_skepticism_score += statement['skepticism_score']

    average_belief_score = total_belief_score / len(statements)
    average_skepticism_score = total_skepticism_score / len(statements)

    if abs(average_belief_score - average_skepticism_score) < 1:
        dominant_attribute = 'balanced'
    elif average_belief_score > average_skepticism_score:
        dominant_attribute = 'belief'
    else:
        dominant_attribute = 'skepticism'

